#!/usr/bin/env node
/**
 * legacy-cleanup-drop-locale.mjs — P3: legacy locale カラム削除 migration 生成
 *
 * 使用法:
 *   node scripts/legacy-cleanup-drop-locale.mjs
 *
 * 出力: supabase/migration_010_legacy_cleanup.sql
 * 前提: admin が手動で availableLocales へ移行済であること
 */

const fs = require("fs")
const path = require("path")

const sql = `-- Migration 010: Drop legacy locale columns from 5 collections
-- Generated by scripts/legacy-cleanup-drop-locale.mjs
-- 冪等 (IF EXISTS) — 安全に実行可能
-- 前提: admin が手動で availableLocales へ移行済であること

DO $$ BEGIN
  ALTER TABLE paradigm.pages DROP COLUMN IF EXISTS locale;
  ALTER TABLE paradigm.services DROP COLUMN IF EXISTS locale;
  ALTER TABLE paradigm.works DROP COLUMN IF EXISTS locale;
  ALTER TABLE paradigm.pricing DROP COLUMN IF EXISTS locale;
  ALTER TABLE paradigm.faqs DROP COLUMN IF EXISTS locale;
END $$;
`

const outPath = path.join(__dirname, "..", "supabase", "migration_010_legacy_cleanup.sql")
fs.writeFileSync(outPath, sql, "utf8")
console.log(`✓ Generated ${outPath}`)